        if (0.0..=1.0).contains(&v) {
            Ok(Self(v))
        } else {
            Err(format!("expected a finite number in [0.0, 1.0], got {v}"))
        }
    }

AFTER (temporary sabotage — a from-scratch reimplementation producing byte-identical messages, with no delegation):
    fn try_from(v: f64) -> Result<Self, Self::Error> {
        if !v.is_finite() {
            return Err(format!("expected a finite number, got {v}"));
